ExecutorService executor = Executors.newFixedThreadPool(2);

Future<Integer> f1 = executor.submit(() -> {
    return (10 / 0);
});

try {
    System.out.println(f1.get());
} catch (Exception e) {
    System.out.println("Catched submit() exception");
}

ThreadPoolExecutor executor = new ThreadPoolExecutor(
        2, 5, 10, TimeUnit.SECONDS, new ArrayBlockingQueue<>(2));

for (int i = 1; i <= 5; i++) {
    int taskId = i;
    executor.execute(() -> {
        System.out.println("Task " + taskId + " by " + Thread.currentThread().getName());
        try { Thread.sleep(2000); } catch (Exception e) {}
    });
}
executor.shutdown();

ThreadPoolExecutor executor = new ThreadPoolExecutor(
        2, 4, 30, TimeUnit.SECONDS, new LinkedBlockingQueue<>());

for (int i = 1; i <= 10; i++) {
    executor.execute(() -> {
        try { Thread.sleep(5000); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    });
}
System.out.println(executor.getPoolSize() + " " + executor.getQueue().size());
